{"cmd":"node --input-type=module <<'EOF'
import { spawnSync } from 'node:child_process';

const cases = [
  ['help', ['--help']],
  ['no_args', []],
  ['missing_key', ['--val', '3']],
  ['missing_val', ['--key', 'a']],
  ['unknown_arg', ['--key', 'a', '--val', '3', '--extra', 'z']],
  ['invalid_int', ['--key', 'a', '--val', 'notint']],
  ['repeated_args', ['--key', 'a', '--key', 'b', '--val', '3', '--val', '4']],
  ['equals_forms', ['--key=b', '--val=3']],
  ['separate_forms', ['--key', 'b', '--val', '3']],
];

const results = cases.map(([name, args]) => {
  const res = spawnSync('/workspace/dataset/test6_executable', args, { encoding: 'utf8' });
  return {
    name,
    args,
    status: res.status,
    signal: res.signal,
    stdout: res.stdout,
    stderr: res.stderr,
    error: res.error ? String(res.error) : null,
  };
});

process.stdout.write(JSON.stringify(results, null, 2));
EOF","workdir":"/workspace","yield_time_ms":30000,"max_output_tokens":20000}
